class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        rows, cols = len(board), len(board[0])
        visit = set()
        found = False

        def backtracking(r, c, index):
            nonlocal found

            if found:
                return 
            if index == len(word):
                found = True
                return
            if (r < 0 or c < 0 or (r,c) in visit or r>=rows or c>=cols or word[index] != board[r][c] ): 
                return

            visit.add((r,c))
            for dr, dc in [(0, -1), (0, 1), (1, 0), (-1, 0)]:
                backtracking(r+dr , c +dc, index+1)
            visit.remove((r,c))


        for r in range(rows):
            for c in range(cols):
                backtracking(r, c, 0)
                if found:
                    return True

        return found

