class Solution:
    def orangesRotting(self, grid: List[List[int]]) -> int:
        count = 0
        q = deque()
        orange = 0

        rows, cols = len(grid), len(grid[0])
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 2:
                    q.append((r,c))
                if grid[r][c] == 1:
                    orange += 1


        while q and orange:
            for _ in range(len(q)):
                r, c = q.popleft()
                for dr, dc in [(-1,0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                        grid[nr][nc] = 2
                        orange -= 1
                        q.append((nr, nc))
            count += 1

        return -1 if orange else count

