class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        # kahn
        adj = defaultdict(list)
        indegree = [0] * numCourses

        for a, b in prerequisites:
            indegree[a] += 1
            adj[b].append(a)

        q = deque()
        for c in range(numCourses):
            if indegree[c] == 0:
                q.append(c)

        finished = 0
        result = []
        while q:
            cur = q.popleft()
            result.append(cur)
            finished += 1

            for c in adj[cur]:
                indegree[c] -= 1
                if indegree[c] == 0:
                    q.append(c)

        if finished == numCourses: return result
        else: return []

class Solution:
    def findRedundantConnection(self, edges: List[List[int]]) -> List[int]:
        parent = list(range(len(edges)+1))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]

            return x


        def union(a,b):
            ra, rb = find(a), find(b)
            if ra == rb: return False
            parent[ra] = rb
            return True

        for edge in edges:
            if not union(edge[0], edge[1]):
                return edge

