class Solution:
    def networkDelayTime(self, times: List[List[int]], n: int, k: int) -> int:
        edges = defaultdict(list)
        for source, dest, time in times:
            edges[source].append((dest, time))

        minheap = [(0, k)]
        visited = set()
        t = 0
        while minheap:
            t1, n1 = heapq.heappop(minheap)
            if n1 in visited:
                continue
            visited.add(n1)
            t = t1

            for n2, t2 in edges[n1]:
                if n2 not in visited:
                    heapq.heappush(minheap, (t+t2, n2))


        return -1 if len(visited) != n else t

class Solution:
    def findCheapestPrice(self, n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:
        prices = [float('inf')] * n
        prices[src] = 0

        for i in range(k+1):
            tempprice = prices.copy()
            for s, d, p in flights:
                if prices[s] == float('inf'):
                    continue
                if prices[s] + p < tempprice[d]:
                    tempprice[d] = prices[s] + p

            prices = tempprice

        return -1 if prices[dst] == float('inf') else prices[dst]

class Solution:
    def climbStairs(self, n: int) -> int:
        step = [0] * (n+1)
        step[0] = 1
        step[1] = 1

        for i in range(2, n+1):
            step[i] = step[i-1] + step[i-2]

        return step[n]
